async def act(page):
    # Plan:
    # 1. Navigate directly to the new simple product form using a relative URL to keep admin language/scope.
    # 2. Fill product Name, SKU, Price using accessibility-role based selectors (get_by_role).
    # 3. Ensure product is Enabled and visible in Catalog+Search if those controls exist.
    # 4. Open the Inventory section (if needed) and set Quantity to 42 and mark In Stock.
    # 5. Set attributes: Size -> 34 and Color -> Blue (using combobox/select where available).
    # 6. Click Save (this is expected to navigate away, so it will be the last action).

    # Note about knowledge_base functions: there are no available helper functions in the provided
    # knowledge base for interacting with this site, so none are used. If such functions existed,
    # we would call them here to perform specific actions (navigation, filling fields, selecting options).

    # 1) Go to the new product page for creating a simple product.
    await page.goto('/index.php/admin/catalog_product/new/set/4/type/simple/')
    await page.wait_for_load_state('networkidle')

    # 2) Fill Name, SKU, Price. Try several reasonable accessible names (case-insensitive match).
    try:
        await page.get_by_role('textbox', name='Name').fill('FancyBoy Man Causal Jeans')
    except Exception:
        try:
            await page.get_by_role('textbox', name='Product Name').fill('FancyBoy Man Causal Jeans')
        except Exception:
            pass

    try:
        await page.get_by_role('textbox', name='SKU').fill('FANCYBOY-MJ-001')
    except Exception:
        try:
            await page.get_by_role('textbox', name='Product SKU').fill('FANCYBOY-MJ-001')
        except Exception:
            pass

    # Price can be a textbox or spinbutton depending on ARIA role
    price_filled = False
    try:
        await page.get_by_role('textbox', name='Price').fill('169.99')
        price_filled = True
    except Exception:
        pass
    if not price_filled:
        try:
            await page.get_by_role('spinbutton', name='Price').fill('169.99')
            price_filled = True
        except Exception:
            pass

    # 3) Status / Visibility
    try:
        # Try to set Status to Enabled
        await page.get_by_role('combobox', name='Status').select_option(label='Enabled')
    except Exception:
        try:
            await page.get_by_role('combobox', name='Status').select_option(value='1')
        except Exception:
            pass

    try:
        # Visibility to Catalog, Search if present
        await page.get_by_role('combobox', name='Visibility').select_option(label='Catalog, Search')
    except Exception:
        try:
            await page.get_by_role('combobox', name='Visibility').select_option(value='4')
        except Exception:
            pass

    # 4) Inventory: open Inventory tab/section if needed, then set qty and in-stock
    # Try clicking a tab or link named Inventory
    try:
        await page.get_by_role('link', name='Inventory').click()
        await page.wait_for_load_state('networkidle')
    except Exception:
        # Some Magento installs render tab as a button or tab role
        try:
            await page.get_by_role('tab', name='Inventory').click()
            await page.wait_for_load_state('networkidle')
        except Exception:
            pass

    # Fill quantity (try several common accessible names/roles)
    qty_set = False
    for role_name in (('spinbutton', 'Qty'), ('spinbutton', 'Quantity'), ('textbox', 'Qty'), ('textbox', 'Quantity')):
        role, name = role_name
        try:
            await page.get_by_role(role, name=name).fill('42')
            qty_set = True
            break
        except Exception:
            continue

    # Mark as In Stock
    try:
        await page.get_by_role('combobox', name='Is In Stock').select_option(label='In Stock')
    except Exception:
        try:
            await page.get_by_role('combobox', name='Stock Availability').select_option(label='In Stock')
        except Exception:
            try:
                await page.get_by_role('combobox', name='Is in Stock').select_option(value='1')
            except Exception:
                pass

    # 5) Attributes: Size and Color - try combobox selectors
    try:
        await page.get_by_role('combobox', name='Size').select_option(label='34')
    except Exception:
        try:
            await page.get_by_role('combobox', name='size').select_option(label='34')
        except Exception:
            pass

    try:
        await page.get_by_role('combobox', name='Color').select_option(label='Blue')
    except Exception:
        try:
            await page.get_by_role('combobox', name='color').select_option(label='Blue')
        except Exception:
            pass

    # 6) Save the product. Use common Save button labels. This is expected to navigate away so it's the last action.
    save_clicked = False
    for label in ('Save', 'Save Product', 'Save and Continue Edit'):
        try:
            await page.get_by_role('button', name=label).click()
            save_clicked = True
            break
        except Exception:
            continue

    # Additional fallbacks for Save if role/button naming differs
    if not save_clicked:
        try:
            # Some themes expose a button with title 'Save'
            await page.get_by_role('button', name='Save Changes').click()
            save_clicked = True
        except Exception:
            try:
                await page.get_by_role('button', name='Submit').click()
                save_clicked = True
            except Exception:
                pass

    if save_clicked:
        await page.wait_for_load_state('networkidle')

